import React, { useState, useEffect, useMemo } from 'react';
import Sidebar, { PageId } from './components/Sidebar';
import RecentLessonsSidebar from './components/RecentLessonsSidebar';
import StudyInput from './components/StudyInput';
import StudyOutput from './components/StudyOutput';
import SettingsModal from './components/SettingsModal';
import LoginModal from './components/LoginModal';
import TeacherChat from './components/TeacherChat';
import Calendar from './components/Calendar';
import SubjectBar, { SUBJECTS } from './components/SubjectBar';
import ArchiveList from './components/ArchiveList';
import AIAgent from './components/AIAgent';
import CurriculumGuide from './components/CurriculumGuide';
import { generateInitialSummary, generateExtendedStudy, generateTopicImage, generateSlideAudio } from './services/geminiService';
import { ProcessingState, StudyResult, StudyFile, DbConfig, UserProfile, Subject, YouTubeVideo, WebPage } from './types';

const App: React.FC = () => {
  const [text, setText] = useState('');
  const [images, setImages] = useState<string[]>([]);
  const [files, setFiles] = useState<StudyFile[]>([]);
  const [ytVideos, setYtVideos] = useState<YouTubeVideo[]>([]);
  const [webPages, setWebPages] = useState<WebPage[]>([]);

  const [activePage, setActivePage] = useState<PageId>('home');
  const [showSettings, setShowSettings] = useState(false);
  const [showLogin, setShowLogin] = useState(false);
  const [showSubjectBar, setShowSubjectBar] = useState(false);
  const [activeSubject, setActiveSubject] = useState<Subject>(SUBJECTS[0]);

  const [leftSidebarOpen, setLeftSidebarOpen] = useState(false);
  const [rightSidebarOpen, setRightSidebarOpen] = useState(false);

  const [dbConfig, setDbConfig] = useState<DbConfig>(() => {
    const saved = localStorage.getItem('gymni_db_config');
    return saved ? JSON.parse(saved) : { url: '', secret: '' };
  });

  const [userProfile, setUserProfile] = useState<UserProfile>(() => {
    const saved = localStorage.getItem('gymni_user_profile');
    return saved ? JSON.parse(saved) : { email: '', isLoggedIn: false, role: 'student' };
  });

  const [state, setState] = useState<ProcessingState>(() => {
    const savedResult = localStorage.getItem('gymni_last_lesson');
    return {
      isLoadingInitial: false,
      isLoadingExtra: false,
      isGeneratingImage: false,
      isGeneratingAudio: false,
      error: null,
      result: savedResult ? JSON.parse(savedResult) : null
    };
  });

  useEffect(() => {
    if (state.result) {
      localStorage.setItem('gymni_last_lesson', JSON.stringify(state.result));
    } else if (!state.isLoadingInitial) {
      localStorage.removeItem('gymni_last_lesson');
    }
  }, [state.result, state.isLoadingInitial]);

  const handleGenerate = async (forcedText?: string) => {
    const inputMsg = forcedText || text;
    if (!inputMsg && images.length === 0 && files.length === 0 && ytVideos.length === 0 && webPages.length === 0) return;

    setState({ isLoadingInitial: true, isLoadingExtra: true, isGeneratingImage: false, isGeneratingAudio: false, error: null, result: null });
    setActivePage('learn');

    const preAnalyses = [
      ...ytVideos.map(v => v.transcript ? `TRANSCRIPT YT: ${v.transcript}` : v.analysis).filter(Boolean),
      ...webPages.map(p => p.analysis).filter(Boolean),
      ...files.map(f => f.analysis).filter(Boolean)
    ] as string[];

    const fullContextText = inputMsg + 
      (ytVideos.length > 0 ? "\nYouTube: " + ytVideos.map(v => v.url).join(', ') : "") +
      (webPages.length > 0 ? "\nWeby: " + webPages.map(p => p.url).join(', ') : "");

    try {
      const initialData = await generateInitialSummary(fullContextText, forcedText ? [] : images, forcedText ? [] : files, preAnalyses);
      setState(prev => ({ 
        ...prev, 
        isLoadingInitial: false, 
        isGeneratingImage: true, 
        result: initialData as StudyResult 
      }));

      if (initialData.title) {
        generateTopicImage(initialData.title).then(imgData => {
          setState(prev => ({
            ...prev,
            isGeneratingImage: false,
            result: prev.result ? { ...prev.result, generatedImage: imgData } : { ...initialData, generatedImage: imgData } as StudyResult
          }));
        });
      }

      if (initialData.fullSummary?.[0]?.text) {
        setState(prev => ({ ...prev, isGeneratingAudio: true }));
        generateSlideAudio(initialData.fullSummary[0].text).then(audioData => {
          setState(prev => ({
            ...prev,
            isGeneratingAudio: false,
            result: prev.result ? { ...prev.result, mainAudio: audioData } : { ...initialData, mainAudio: audioData } as StudyResult
          }));
        });
      }

      generateExtendedStudy(fullContextText, forcedText ? [] : images, forcedText ? [] : files).then(extra => {
        setState(prev => {
          const base = prev.result || (initialData as StudyResult);
          return {
            ...prev,
            isLoadingExtra: false,
            result: { ...base, ...extra }
          };
        });
      });

    } catch (err: any) {
      setState({ isLoadingInitial: false, isLoadingExtra: false, isGeneratingImage: false, isGeneratingAudio: false, error: 'Analýza přerušena.', result: null });
    }
  };

  const handleReset = () => {
    localStorage.removeItem('gymni_last_lesson');
    setState({ isLoadingInitial: false, isLoadingExtra: false, isGeneratingImage: false, isGeneratingAudio: false, error: null, result: null });
    setText('');
    setImages([]);
    setFiles([]);
    setYtVideos([]);
    setWebPages([]);
    setActivePage('learn');
  };

  const handleOpenArchivedItem = (r: StudyResult) => {
    setState(s => ({...s, result: r, isLoadingInitial: false, isLoadingExtra: false}));
    setActivePage('learn');
    setRightSidebarOpen(false);
  };

  const renderContent = () => {
    switch (activePage) {
      case 'home':
        return (
          <div className="max-w-7xl mx-auto py-8 md:py-12 px-4 space-y-10 animate-fade">
            <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 pb-10 border-b border-white/5 relative">
              <div className="relative z-10">
                <p className="text-indigo-500 text-[10px] font-black uppercase tracking-[0.5em] mb-3 ml-1">Gymni Mate Workspace</p>
                <h1 className="text-5xl md:text-6xl font-black uppercase tracking-tighter text-white">
                  <span className="text-indigo-500">{activeSubject.name}</span> Workspace
                </h1>
              </div>
              <div className="flex gap-4">
                 <button onClick={() => setActivePage('learn')} className="px-10 py-5 rounded-[2rem] btn-gradient text-white font-black uppercase text-[11px] tracking-widest shadow-[0_20px_50px_rgba(99,102,241,0.3)] hover:scale-105 transition-all active:scale-95">Nová lekce</button>
              </div>
              <div className="absolute -top-20 -left-20 w-96 h-96 bg-indigo-600/10 rounded-full blur-[120px] pointer-events-none"></div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
              <div className="lg:col-span-8 space-y-10">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className={`p-10 rounded-[3rem] border transition-all relative overflow-hidden group cursor-pointer ${state.result ? 'bg-indigo-600/10 border-indigo-500/20' : 'bg-zinc-950 border-white/5'}`} onClick={() => setActivePage('learn')}>
                    <div className="relative z-10">
                      <h3 className="text-sm font-black uppercase tracking-widest text-zinc-500 mb-6 flex items-center gap-3">
                        {state.result ? <span className="flex h-2 w-2 rounded-full bg-indigo-500 animate-pulse"></span> : null}
                        {state.result ? 'Rozpracováno' : 'Status'}
                      </h3>
                      {state.result ? (
                        <div className="space-y-4">
                           <p className="text-2xl font-black text-white leading-tight uppercase tracking-tight line-clamp-2">{state.result.title}</p>
                           <p className="text-[10px] font-black uppercase tracking-widest text-indigo-400">Klikni pro pokračování ve studiu <i className="fa-solid fa-arrow-right ml-2"></i></p>
                        </div>
                      ) : (
                        <div className="space-y-4">
                           <p className="text-xl font-bold text-zinc-600 leading-tight">Zatím neprobíhá žádná aktivní lekce.</p>
                           <p className="text-[10px] font-black uppercase tracking-widest text-zinc-700">Připraven k analýze tvých materiálů</p>
                        </div>
                      )}
                    </div>
                    {state.result && <div className="absolute top-0 right-0 p-10 opacity-5 group-hover:scale-110 transition-transform"><i className="fa-solid fa-brain text-8xl"></i></div>}
                  </div>

                  <div className="p-10 rounded-[3rem] bg-zinc-950 border border-white/5 hover:border-indigo-500/20 transition-all shadow-2xl flex flex-col justify-between">
                    <div>
                      <h3 className="text-sm font-black uppercase tracking-widest text-zinc-500 mb-6">Doporučení</h3>
                      <p className="text-zinc-400 font-bold text-sm leading-relaxed">Na základě tvých předmětů ti doporučujeme zopakovat <strong>Molekulární biologii</strong> pro zítřejší test.</p>
                    </div>
                    <button onClick={() => setActivePage('curriculum')} className="mt-8 text-[10px] font-black uppercase tracking-widest text-indigo-500 flex items-center gap-2 hover:translate-x-1 transition-transform">Průvodce učivem <i className="fa-solid fa-sparkles"></i></button>
                  </div>
                </div>

                <div className="space-y-6">
                  <div className="flex items-center justify-between px-4">
                    <h3 className="text-xs font-black uppercase tracking-[0.4em] text-zinc-600">Poslední aktivita</h3>
                    <button onClick={() => setActivePage('archive')} className="text-[10px] font-black uppercase tracking-widest text-indigo-500 hover:underline">Zobrazit vše</button>
                  </div>
                  <ArchiveList config={dbConfig} onOpenItem={handleOpenArchivedItem} limit={2} />
                </div>
              </div>

              <div className="lg:col-span-4 space-y-10">
                <Calendar role={userProfile.role} />
                <div className="p-8 rounded-[2.5rem] bg-zinc-950/50 border border-white/5 backdrop-blur-xl">
                   <h4 className="text-[10px] font-black uppercase tracking-widest text-zinc-500 mb-6">Předplatné & Limit</h4>
                   <div className="space-y-4">
                      <div className="flex justify-between items-end mb-2">
                        <span className="text-[10px] font-black uppercase text-white">Využití paměti</span>
                        <span className="text-[10px] font-black text-indigo-400">1.2 / 5 GB</span>
                      </div>
                      <div className="h-1.5 w-full bg-white/5 rounded-full overflow-hidden">
                        <div className="h-full bg-indigo-500 w-[24%]"></div>
                      </div>
                      <p className="text-[9px] text-zinc-600 font-bold uppercase tracking-widest mt-4 leading-relaxed">Jako Platinum člen máš prioritní přístup k Gemini 3 Pro.</p>
                   </div>
                </div>
              </div>
            </div>
          </div>
        );
      case 'curriculum':
        return <CurriculumGuide activeSubject={activeSubject} onGenerateLesson={(t) => handleGenerate(t)} />;
      case 'learn':
        return (
          <div className="animate-fade flex flex-col items-center">
            {(!state.result && !state.isLoadingInitial) && (
              <div className="text-center space-y-4 mb-16 max-w-4xl pt-20 w-full px-4">
                <p className="text-indigo-500 text-[10px] font-black uppercase tracking-[0.8em] mb-4">Neural Learning Engine</p>
                <h1 className="text-5xl md:text-7xl font-black tracking-tighter mb-10 uppercase text-white tracking-widest">{activeSubject.name}</h1>
                <StudyInput 
                  text={text} setText={setText} images={images} setImages={setImages} files={files} setFiles={setFiles} ytVideos={ytVideos} setYtVideos={setYtVideos} webPages={webPages} setWebPages={setWebPages} onGenerate={() => handleGenerate()} isLoading={state.isLoadingInitial} 
                />
              </div>
            )}
            {(state.isLoadingInitial || state.result) && (
              <StudyOutput 
                result={state.result} onReset={handleReset} onUpdateResult={(r) => setState(s => ({...s, result: r}))} onGenerateTopic={(t) => handleGenerate(`Nauč mě o: ${t}`)} isLoadingExtra={state.isLoadingExtra} isLoadingInitial={state.isLoadingInitial} isGeneratingImage={state.isGeneratingImage} isGeneratingAudio={state.isGeneratingAudio} dbConfig={dbConfig} originalImage={images[0] || null} originalText={text} activeSubject={activeSubject} 
              />
            )}
          </div>
        );
      case 'archive':
        return (
          <div className="max-w-6xl mx-auto py-12 px-6 space-y-12 animate-fade">
             <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 border-b border-white/5 pb-10">
               <h2 className="text-4xl font-black uppercase tracking-tight text-white">Knihovna znalostí</h2>
               <button onClick={() => setActivePage('learn')} className="px-8 py-3.5 rounded-2xl bg-white/5 border border-white/10 text-zinc-400 text-[10px] font-black uppercase tracking-widest">Nové studium</button>
             </div>
             <ArchiveList config={dbConfig} onOpenItem={handleOpenArchivedItem} />
          </div>
        );
      case 'chat': return <div className="max-w-7xl mx-auto h-[80vh] px-4"><TeacherChat initialSubject={activeSubject.name} /></div>;
      default: return null;
    }
  };

  return (
    <div className="flex h-screen bg-[#020617] text-[#f1f5f9] selection:bg-indigo-500 selection:text-white overflow-hidden relative">
      <Sidebar 
        activePage={activePage} onPageChange={setActivePage} hasResult={!!state.result} userProfile={userProfile} onUpdateProfile={setUserProfile} onOpenLogin={() => setShowLogin(true)} activeSubject={activeSubject} onToggleSubjectBar={() => setShowSubjectBar(!showSubjectBar)} onOpenSettings={() => setShowSettings(true)} isOpen={leftSidebarOpen} onToggle={() => setLeftSidebarOpen(!leftSidebarOpen)}
      />
      <div className="flex-grow flex flex-col min-w-0 relative z-10 transition-all duration-700 overflow-hidden bg-black/5">
        <main className="flex-grow overflow-y-auto p-4 md:p-8 no-scrollbar relative">{renderContent()}</main>
        <SubjectBar activeSubjectId={activeSubject.id} onSelect={setActiveSubject} isOpen={showSubjectBar} onClose={() => setShowSubjectBar(false)} />
      </div>
      {(activePage === 'learn' || activePage === 'curriculum') && (
        <RecentLessonsSidebar config={dbConfig} onOpenItem={handleOpenArchivedItem} isOpen={rightSidebarOpen} onToggle={() => setRightSidebarOpen(!rightSidebarOpen)} />
      )}
      <AIAgent currentContext={state.result} />
      {showSettings && <SettingsModal config={dbConfig} onSave={setDbConfig} onClose={() => setShowSettings(false)} />}
      {showLogin && <LoginModal onLogin={setUserProfile} onClose={() => setShowLogin(false)} />}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import Sidebar, { PageId } from './components/Sidebar';
import RecentLessonsSidebar from './components/RecentLessonsSidebar';
import StudyInput from './components/StudyInput';
import StudyOutput from './components/StudyOutput';
import SettingsModal from './components/SettingsModal';
import LoginModal from './components/LoginModal';
import TeacherChat from './components/TeacherChat';
import Calendar from './components/Calendar';
import SubjectBar, { SUBJECTS } from './components/SubjectBar';
import ArchiveList from './components/ArchiveList';
import AIAgent from './components/AIAgent';
import CurriculumGuide from './components/CurriculumGuide';
import { generateInitialSummary, generateExtendedStudy, generateTopicImage, generateSlideAudio } from './services/geminiService';
import { ProcessingState, StudyResult, StudyFile, DbConfig, UserProfile, Subject, YouTubeVideo, WebPage } from './types';

// Helper for safe JSON parsing
const safeJsonParse = (key: string, fallback: any) => {
  try {
    const saved = localStorage.getItem(key);
    return saved ? JSON.parse(saved) : fallback;
  } catch (e) {
    console.warn(`Chyba při parsování ${key}:`, e);
    return fallback;
  }
};

const App: React.FC = () => {
  const [text, setText] = useState('');
  const [images, setImages] = useState<string[]>([]);
  const [files, setFiles] = useState<StudyFile[]>([]);
  const [ytVideos, setYtVideos] = useState<YouTubeVideo[]>([]);
  const [webPages, setWebPages] = useState<WebPage[]>([]);

  const [activePage, setActivePage] = useState<PageId>('home');
  const [showSettings, setShowSettings] = useState(false);
  const [showLogin, setShowLogin] = useState(false);
  const [showSubjectBar, setShowSubjectBar] = useState(false);

  // Safe initialization
  const [activeSubject, setActiveSubject] = useState<Subject>(() => {
    return SUBJECTS[0] || { id: 'default', name: 'Studium', icon: 'fa-graduation-cap', color: 'bg-indigo-500' };
  });

  const [leftSidebarOpen, setLeftSidebarOpen] = useState(false);
  const [rightSidebarOpen, setRightSidebarOpen] = useState(false);

  const [dbConfig, setDbConfig] = useState<DbConfig>(() => 
    safeJsonParse('gymni_db_config', { url: '', secret: '' })
  );

  const [userProfile, setUserProfile] = useState<UserProfile>(() => 
    safeJsonParse('gymni_user_profile', { email: '', isLoggedIn: false, role: 'student' })
  );

  const [state, setState] = useState<ProcessingState>(() => {
    const savedResult = safeJsonParse('gymni_last_lesson', null);
    return {
      isLoadingInitial: false,
      isLoadingExtra: false,
      isGeneratingImage: false,
      isGeneratingAudio: false,
      error: null,
      result: savedResult
    };
  });

  useEffect(() => {
    if (state.result) {
      localStorage.setItem('gymni_last_lesson', JSON.stringify(state.result));
    } else if (!state.isLoadingInitial) {
      localStorage.removeItem('gymni_last_lesson');
    }
  }, [state.result, state.isLoadingInitial]);

  const handleGenerate = async (forcedText?: string) => {
    const inputMsg = forcedText || text;
    if (!inputMsg && images.length === 0 && files.length === 0 && ytVideos.length === 0 && webPages.length === 0) return;

    setState({ isLoadingInitial: true, isLoadingExtra: true, isGeneratingImage: false, isGeneratingAudio: false, error: null, result: null });
    setActivePage('learn');

    const preAnalyses = [
      ...ytVideos.map(v => v.transcript ? `TRANSCRIPT YT: ${v.transcript}` : v.analysis).filter(Boolean),
      ...webPages.map(p => p.analysis).filter(Boolean),
      ...files.map(f => f.analysis).filter(Boolean)
    ] as string[];

    const fullContextText = inputMsg + 
      (ytVideos.length > 0 ? "\nYouTube: " + ytVideos.map(v => v.url).join(', ') : "") +
      (webPages.length > 0 ? "\nWeby: " + webPages.map(p => p.url).join(', ') : "");

    try {
      const initialData = await generateInitialSummary(fullContextText, forcedText ? [] : images, forcedText ? [] : files, preAnalyses);
      const studyResult = {
        title: initialData.title || "Nová lekce",
        fullSummary: initialData.fullSummary || [],
        ...initialData
      } as StudyResult;

      setState(prev => ({ 
        ...prev, 
        isLoadingInitial: false, 
        isGeneratingImage: true, 
        result: studyResult
      }));

      if (studyResult.title) {
        generateTopicImage(studyResult.title).then(imgData => {
          setState(prev => ({
            ...prev,
            isGeneratingImage: false,
            result: prev.result ? { ...prev.result, generatedImage: imgData } : null
          }));
        });
      }

      if (studyResult.fullSummary?.[0]?.text) {
        setState(prev => ({ ...prev, isGeneratingAudio: true }));
        generateSlideAudio(studyResult.fullSummary[0].text).then(audioData => {
          setState(prev => ({
            ...prev,
            isGeneratingAudio: false,
            result: prev.result ? { ...prev.result, mainAudio: audioData } : null
          }));
        });
      }

      generateExtendedStudy(fullContextText, forcedText ? [] : images, forcedText ? [] : files).then(extra => {
        setState(prev => {
          if (!prev.result) return prev;
          return {
            ...prev,
            isLoadingExtra: false,
            result: { ...prev.result, ...extra }
          };
        });
      });

    } catch (err: any) {
      setState({ isLoadingInitial: false, isLoadingExtra: false, isGeneratingImage: false, isGeneratingAudio: false, error: 'Analýza přerušena.', result: null });
    }
  };

  const handleReset = () => {
    localStorage.removeItem('gymni_last_lesson');
    setState({ isLoadingInitial: false, isLoadingExtra: false, isGeneratingImage: false, isGeneratingAudio: false, error: null, result: null });
    setText('');
    setImages([]);
    setFiles([]);
    setYtVideos([]);
    setWebPages([]);
    setActivePage('learn');
  };

  const handleOpenArchivedItem = (r: StudyResult) => {
    setState(s => ({...s, result: r, isLoadingInitial: false, isLoadingExtra: false}));
    setActivePage('learn');
    setRightSidebarOpen(false);
  };

  const renderContent = () => {
    switch (activePage) {
      case 'home':
        return (
          <div className="max-w-7xl mx-auto py-8 md:py-12 px-4 space-y-10 animate-fade">
            <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 pb-10 border-b border-white/5 relative">
              <div className="relative z-10">
                <p className="text-indigo-500 text-[10px] font-black uppercase tracking-[0.5em] mb-3 ml-1">Gymni Mate Workspace</p>
                <h1 className="text-5xl md:text-6xl font-black uppercase tracking-tighter text-white">
                  <span className="text-indigo-500">{activeSubject.name}</span> Workspace
                </h1>
              </div>
              <div className="flex gap-4">
                 <button onClick={() => setActivePage('learn')} className="px-10 py-5 rounded-[2rem] btn-gradient text-white font-black uppercase text-[11px] tracking-widest shadow-[0_20px_50px_rgba(99,102,241,0.3)] hover:scale-105 transition-all active:scale-95">Nová lekce</button>
              </div>
              <div className="absolute -top-20 -left-20 w-96 h-96 bg-indigo-600/10 rounded-full blur-[120px] pointer-events-none"></div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
              <div className="lg:col-span-8 space-y-10">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className={`p-10 rounded-[3rem] border transition-all relative overflow-hidden group cursor-pointer ${state.result ? 'bg-indigo-600/10 border-indigo-500/20' : 'bg-zinc-950 border-white/5'}`} onClick={() => setActivePage('learn')}>
                    <div className="relative z-10">
                      <h3 className="text-sm font-black uppercase tracking-widest text-zinc-500 mb-6 flex items-center gap-3">
                        {state.result ? <span className="flex h-2 w-2 rounded-full bg-indigo-500 animate-pulse"></span> : null}
                        {state.result ? 'Rozpracováno' : 'Status'}
                      </h3>
                      {state.result ? (
                        <div className="space-y-4">
                           <p className="text-2xl font-black text-white leading-tight uppercase tracking-tight line-clamp-2">{state.result.title}</p>
                           <p className="text-[10px] font-black uppercase tracking-widest text-indigo-400">Klikni pro pokračování ve studiu <i className="fa-solid fa-arrow-right ml-2"></i></p>
                        </div>
                      ) : (
                        <div className="space-y-4">
                           <p className="text-xl font-bold text-zinc-600 leading-tight">Zatím neprobíhá žádná aktivní lekce.</p>
                           <p className="text-[10px] font-black uppercase tracking-widest text-zinc-700">Připraven k analýze tvých materiálů</p>
                        </div>
                      )}
                    </div>
                    {state.result && <div className="absolute top-0 right-0 p-10 opacity-5 group-hover:scale-110 transition-transform"><i className="fa-solid fa-brain text-8xl"></i></div>}
                  </div>

                  <div className="p-10 rounded-[3rem] bg-zinc-950 border border-white/5 hover:border-indigo-500/20 transition-all shadow-2xl flex flex-col justify-between">
                    <div>
                      <h3 className="text-sm font-black uppercase tracking-widest text-zinc-500 mb-6">Doporučení</h3>
                      <p className="text-zinc-400 font-bold text-sm leading-relaxed">Na základě tvých předmětů ti doporučujeme zopakovat <strong>Molekulární biologii</strong> pro zítřejší test.</p>
                    </div>
                    <button onClick={() => setActivePage('curriculum')} className="mt-8 text-[10px] font-black uppercase tracking-widest text-indigo-500 flex items-center gap-2 hover:translate-x-1 transition-transform">Průvodce učivem <i className="fa-solid fa-sparkles"></i></button>
                  </div>
                </div>

                <div className="space-y-6">
                  <div className="flex items-center justify-between px-4">
                    <h3 className="text-xs font-black uppercase tracking-[0.4em] text-zinc-600">Poslední aktivita</h3>
