const ArchiveList: React.FC<ArchiveListProps> = ({ config, onOpenItem, limit }) => {
  const [items, setItems] = useState<ArchiveItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await fetchArchive(config);
      setItems(data.archive || []);
    } catch (e: any) {
      console.warn("Chyba při načítání archivu:", e);
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); }, [config]);

  const handleDelete = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (!confirm("Opravdu smazat tuto lekci? Tato akce je nevratná.")) return;
    try {
      await deleteArchiveItem(config, id);
      setItems(prev => prev.filter(i => i.id !== id));
    } catch (e: any) {
      alert("Chyba: " + e.message);
    }
  };

  if (loading) return (
    <div className="flex flex-col items-center justify-center py-32 gap-6 opacity-40">
      <div className="w-12 h-12 border-4 border-indigo-500/20 border-t-indigo-500 rounded-full animate-spin"></div>
