        >
          {item.image_url ? (
            <div className="h-48 overflow-hidden relative shrink-0">
              <img src={`${baseUrl}${item.image_url}`} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-1000" alt={item.topic} />
              <div className="absolute inset-0 bg-gradient-to-t from-[#030712] via-transparent to-transparent"></div>
            </div>
          ) : (
            <div className="h-48 bg-zinc-950 flex items-center justify-center shrink-0">
               <i className="fa-solid fa-brain text-zinc-800 text-6xl"></i>
            </div>
          )}

          <div className="p-10 flex-grow flex flex-col">
            <div className="flex items-center gap-3 mb-4">
              <div className="w-2 h-2 rounded-full bg-indigo-500"></div>
              <span className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-500">
