                <div className="flex items-center gap-1.5 text-zinc-600">
                  <i className="fa-solid fa-file-lines text-[10px]"></i>
                  <span className="text-[9px] font-black">{item.study_json?.fullSummary?.length || 0}</span>
                </div>
                <div className="flex items-center gap-1.5 text-zinc-600">
