import React, { useState, useEffect, useRef, useMemo } from 'react';
import { GoogleGenAI, Type } from "@google/genai";

// --- TYPES ---
interface Flashcard { front: string; back: string; }
interface QuizQuestion { question: string; options: string[]; correctIndex: number; }
interface StudyResult {
  title: string;
  summary: string;
  keyPoints: string[];
  flashcards: Flashcard[];
  quiz: QuizQuestion[];
}

// --- UTILS ---
const safeJsonParse = (str: string) => {
  try { return JSON.parse(str); }
  catch (e) { return null; }
};

// --- COMPONENTS ---

// KaTeX Renderer with safety check
const MathRenderer: React.FC<{ tex: string; block?: boolean }> = ({ tex, block }) => {
  const containerRef = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    if (containerRef.current && (window as any).katex) {
      try {
        (window as any).katex.render(tex, containerRef.current, {
          throwOnError: false,
          displayMode: block,
          macros: { "\\ce": "\\ce" }
        });
      } catch (e) {
        containerRef.current.textContent = tex;
      }
    }
  }, [tex, block]);
  return <span ref={containerRef} className={block ? "block my-4" : "inline-block"} />;
};

// Formatter for rich text + math
const RichText: React.FC<{ text: string }> = ({ text }) => {
  const parts = useMemo(() => {
    if (!text) return [];
    // Split by math delimiters $...$ or $$...$$
    return text.split(/(\$\$[\s\S]*?\$\$|\$[^$]+\$)/g);
  }, [text]);

  return (
    <div className="leading-relaxed text-zinc-300">
      {parts.map((part, i) => {
        if (part.startsWith('$$')) return <MathRenderer key={i} tex={part.slice(2, -2)} block />;
        if (part.startsWith('$')) return <MathRenderer key={i} tex={part.slice(1, -1)} />;
        return <span key={i} dangerouslySetInnerHTML={{ __html: part.replace(/\*\*(.*?)\*\*/g, '<strong class="text-white font-black">$1</strong>').replace(/\n/g, '<br/>') }} />;
      })}
    </div>
  );
};

