// Internal Quiz Component
const Quiz: React.FC<{ questions: QuizQuestion[] }> = ({ questions }) => {
  const [current, setCurrent] = useState(0);
  const [selected, setSelected] = useState<number | null>(null);
  const [score, setScore] = useState(0);
  const [finished, setFinished] = useState(false);

  const handleSelect = (idx: number) => {
    if (selected !== null) return;
    setSelected(idx);
    if (idx === questions[current].correctIndex) setScore(s => s + 1);
  };

  const next = () => {
    if (current < questions.length - 1) {
      setCurrent(c => c + 1);
      setSelected(null);
    } else {
      setFinished(true);
    }
  };

  if (finished) return (
    <div className="p-16 text-center bg-zinc-950 rounded-[3rem] border border-white/5 animate-fade">
      <h3 className="text-5xl font-black text-indigo-500 mb-4">{Math.round((score/questions.length)*100)}%</h3>
      <p className="text-zinc-500 font-bold uppercase tracking-widest text-sm mb-10">Tvůj výsledek v testu</p>
      <button onClick={() => {setCurrent(0); setScore(0); setFinished(false); setSelected(null);}} className="px-10 py-4 rounded-2xl bg-white/5 text-[10px] font-black uppercase tracking-widest">Zkusit znovu</button>
    </div>
  );

  const q = questions[current];

  return (
    <div className="p-10 rounded-[3rem] bg-zinc-950 border border-white/5 shadow-2xl animate-fade">
      <div className="flex justify-between items-center mb-10">
        <span className="text-[10px] font-black uppercase tracking-widest text-indigo-500">Otázka {current + 1} / {questions.length}</span>
      </div>
      <p className="text-2xl font-black text-white mb-10 leading-tight uppercase tracking-tight">{q.question}</p>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {q.options.map((opt, i) => {
          const isCorrect = i === q.correctIndex;
          const isSelected = i === selected;
          return (
            <button
              key={i}
              onClick={() => handleSelect(i)}
              className={`p-6 rounded-[1.5rem] text-left text-sm font-bold border transition-all ${
                selected === null ? 'bg-white/5 border-white/5 hover:border-indigo-500/50' :
                isCorrect ? 'bg-emerald-500/20 border-emerald-500 text-emerald-400' :
                isSelected ? 'bg-red-500/20 border-red-500 text-red-400' : 'bg-white/5 border-white/5 opacity-30'
              }`}
            >
              {opt}
            </button>
          );
        })}
      </div>
      {selected !== null && (
        <button onClick={next} className="w-full mt-10 py-5 rounded-[2rem] bg-indigo-600 text-white font-black uppercase text-[10px] tracking-widest shadow-xl">
          Další otázka
        </button>
      )}
    </div>
  );
};

export default App;

