// --- HELPERS ---
const safeJsonParse = (str: string) => {
  try { return JSON.parse(str.replace(/```json|```/g, '').trim()); }
  catch (e) { return null; }
};

const MathRenderer: React.FC<{ tex: string; block?: boolean }> = ({ tex, block }) => {
  const containerRef = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    if (containerRef.current && (window as any).katex) {
      try {
        (window as any).katex.render(tex, containerRef.current, {
          throwOnError: false,
          displayMode: block,
          macros: { "\\ce": "\\ce" }
        });
      } catch (e) {
        containerRef.current.textContent = tex;
      }
    }
  }, [tex, block]);
  return <span ref={containerRef} className={block ? "block my-6" : "inline-block mx-1 text-indigo-300 font-bold"} />;
};

const FormattedText: React.FC<{ text: string }> = ({ text }) => {
  const parts = useMemo(() => {
    if (!text) return [];
    return text.split(/(\$\$[\s\S]*?\$\$|\$[^$]+\$)/g);
  }, [text]);

  return (
    <div className="leading-relaxed text-zinc-300 whitespace-pre-wrap">
      {parts.map((part, i) => {
        if (part.startsWith('$$')) return <MathRenderer key={i} tex={part.slice(2, -2)} block />;
        if (part.startsWith('$')) return <MathRenderer key={i} tex={part.slice(1, -1)} />;
        return <span key={i} dangerouslySetInnerHTML={{ __html: part.replace(/\*\*(.*?)\*\*/g, '<strong class="text-white font-black">$1</strong>') }} />;
      })}
    </div>
  );
};

