const Quiz: React.FC<{ questions: QuizQuestion[] }> = ({ questions }) => {
  const [current, setCurrent] = useState(0);
  const [selected, setSelected] = useState<number | null>(null);
  const [score, setScore] = useState(0);
  const [finished, setFinished] = useState(false);

  const handleSelect = (idx: number) => {
    if (selected !== null) return;
    setSelected(idx);
    if (idx === questions[current].correctIndex) setScore(s => s + 1);
  };

  const handleNext = () => {
    if (current < questions.length - 1) {
      setCurrent(c => c + 1);
      setSelected(null);
    } else {
      setFinished(true);
    }
  };

  if (finished) return (
    <div className="p-16 text-center glass-panel rounded-[3rem] animate-fade">
      <div className="w-24 h-24 bg-indigo-600/20 rounded-full flex items-center justify-center mx-auto mb-8 border border-indigo-500/20 shadow-2xl">
        <i className="fa-solid fa-trophy text-indigo-500 text-4xl"></i>
      </div>
      <h3 className="text-5xl font-black text-white mb-2 uppercase tracking-tight">Váš výsledek</h3>
      <p className="text-indigo-500 text-2xl font-black mb-10">{Math.round((score/questions.length)*100)}% Úspěšnost</p>
      <button onClick={() => window.location.reload()} className="px-12 py-5 rounded-2xl btn-gradient text-white font-black uppercase text-[11px] tracking-widest shadow-xl transition-all hover:scale-105 active:scale-95">Opakovat lekci</button>
    </div>
  );

  const q = questions[current];

  return (
    <div className="glass-panel p-10 md:p-16 rounded-[3rem] shadow-2xl animate-fade relative overflow-hidden">
      <div className="absolute top-0 left-0 w-full h-1 bg-white/5">
        <div className="h-full bg-indigo-500 transition-all duration-700" style={{ width: `${((current + 1) / questions.length) * 100}%` }}></div>
      </div>
      <div className="flex justify-between items-center mb-12">
        <span className="text-[10px] font-black uppercase tracking-widest text-indigo-500">Analytický kvíz</span>
        <span className="text-[10px] font-black uppercase text-zinc-600">Otázka {current + 1} / {questions.length}</span>
      </div>
      <h3 className="text-2xl md:text-3xl font-black text-white mb-12 leading-tight uppercase tracking-tight logo-font">{q.question}</h3>
      <div className="grid grid-cols-1 gap-4">
        {q.options.map((opt, i) => (
          <button
            key={i}
            onClick={() => handleSelect(i)}
            className={`p-6 rounded-2xl text-left text-sm font-bold border transition-all flex items-center justify-between group ${
              selected === null ? 'bg-white/5 border-white/5 hover:border-indigo-500/50 hover:bg-white/10' :
              i === q.correctIndex ? 'bg-emerald-500/20 border-emerald-500 text-emerald-400' :
              selected === i ? 'bg-red-500/20 border-red-500 text-red-400' : 'bg-white/5 border-white/5 opacity-30'
            }`}
          >
            <span className="uppercase tracking-wide">{opt}</span>
            {selected !== null && i === q.correctIndex && <i className="fa-solid fa-check text-emerald-500"></i>}
            {selected === i && i !== q.correctIndex && <i className="fa-solid fa-xmark text-red-500"></i>}
          </button>
        ))}
      </div>
      {selected !== null && (
        <button onClick={handleNext} className="w-full mt-12 py-6 rounded-[2rem] bg-indigo-600 text-white font-black uppercase text-[11px] tracking-[0.3em] shadow-2xl transition-all hover:bg-indigo-500">
          Další fáze testu
        </button>
      )}
    </div>
  );
};

