import { GoogleGenAI, Type } from "@google/genai";

// --- TYPES & INTERFACES ---
interface Flashcard { front: string; back: string; }
interface QuizQuestion { question: string; options: string[]; correctIndex: number; }
interface StudyResult {
  title: string;
  summary: string;
  keyInsights: string[];
  flashcards: Flashcard[];
  quiz: QuizQuestion[];
}

// --- UTILS ---
const safeJsonParse = (str: string) => {
  try {
    // Odstranění markdown bloků pokud existují
    const cleaned = str.replace(/```json|```/g, '').trim();
    return JSON.parse(cleaned);
  } catch (e) {
    console.error("JSON Parse Error:", e);
    return null;
  }
};

// --- COMPONENTS ---

// Robustní renderer matematiky
const MathRenderer: React.FC<{ tex: string; block?: boolean }> = ({ tex, block }) => {
  const containerRef = useRef<HTMLSpanElement>(null);

  useEffect(() => {
    if (containerRef.current && (window as any).katex) {
      try {
        (window as any).katex.render(tex, containerRef.current, {
          throwOnError: false,
          displayMode: block,
          macros: { "\\ce": "\\ce" }
        });
      } catch (e) {
        containerRef.current.textContent = tex;
      }
    }
  }, [tex, block]);

  return <span ref={containerRef} className={block ? "block w-full overflow-x-auto my-4" : "inline-block mx-0.5 text-indigo-300 font-semibold"} />;
};

// Formátování textu (Markdown-ish + KaTeX)
const RichText: React.FC<{ text: string }> = ({ text }) => {
  const parts = useMemo(() => {
    if (!text) return [];
    // Split podle $$...$$ nebo $...$
    return text.split(/(\$\$[\s\S]*?\$\$|\$[^$]+\$)/g);
  }, [text]);

  return (
    <div className="leading-relaxed text-zinc-300 whitespace-pre-wrap">
      {parts.map((part, i) => {
        if (part.startsWith('$$')) return <MathRenderer key={i} tex={part.slice(2, -2)} block />;
        if (part.startsWith('$')) return <MathRenderer key={i} tex={part.slice(1, -1)} />;

        // Zpracování tučného písma a odřádkování
        const formatted = part
          .replace(/\*\*(.*?)\*\*/g, '<strong class="text-white font-extrabold">$1</strong>')
          .replace(/\n/g, '<br/>');

        return <span key={i} dangerouslySetInnerHTML={{ __html: formatted }} />;
      })}
    </div>
  );
};

// Kvízová komponenta
const Quiz: React.FC<{ questions: QuizQuestion[] }> = ({ questions }) => {
  const [current, setCurrent] = useState(0);
  const [selected, setSelected] = useState<number | null>(null);
  const [score, setScore] = useState(0);
  const [finished, setFinished] = useState(false);

  const handleAnswer = (idx: number) => {
    if (selected !== null) return;
    setSelected(idx);
    if (idx === questions[current].correctIndex) setScore(s => s + 1);
  };

  const handleNext = () => {
    if (current < questions.length - 1) {
      setCurrent(c => c + 1);
      setSelected(null);
    } else {
      setFinished(true);
    }
  };

  if (finished) return (
    <div className="p-16 text-center glass-panel rounded-[3rem] border-white/10 animate-fade">
      <div className="w-24 h-24 bg-indigo-600/20 rounded-full flex items-center justify-center mx-auto mb-8 border border-indigo-500/20">
        <i className="fa-solid fa-trophy text-indigo-500 text-4xl"></i>
      </div>
      <h3 className="text-4xl font-black text-white mb-2 uppercase tracking-tight">Výborně!</h3>
      <p className="text-indigo-400 text-xl font-black mb-10">{Math.round((score/questions.length)*100)}% Úspěšnost</p>
      <button onClick={() => window.location.reload()} className="px-12 py-5 rounded-2xl btn-gradient text-white font-black uppercase text-[11px] tracking-widest transition-all hover:scale-105 active:scale-95">Nová lekce</button>
    </div>
  );

  const q = questions[current];

  return (
    <div className="glass-panel p-10 md:p-14 rounded-[3rem] shadow-2xl animate-fade">
      <div className="flex justify-between items-center mb-10">
        <span className="text-[10px] font-black uppercase tracking-widest text-indigo-500">Znalostní test</span>
        <span className="text-[10px] font-black uppercase text-zinc-600">Otázka {current + 1} / {questions.length}</span>
      </div>
      <h3 className="text-2xl md:text-3xl font-black text-white mb-10 leading-tight uppercase tracking-tight logo-font">{q.question}</h3>
      <div className="grid grid-cols-1 gap-4">
        {q.options.map((opt, i) => {
          const isCorrect = i === q.correctIndex;
          const isSelected = i === selected;
          return (
            <button
              key={i}
              onClick={() => handleAnswer(i)}
              className={`p-6 rounded-2xl text-left text-sm font-bold border transition-all flex items-center justify-between ${
                selected === null ? 'bg-white/5 border-white/5 hover:border-indigo-500/50 hover:bg-white/10' :
                isCorrect ? 'bg-emerald-500/20 border-emerald-500 text-emerald-400' :
                isSelected ? 'bg-red-500/20 border-red-500 text-red-400' : 'bg-white/5 border-white/5 opacity-30'
              }`}
            >
              <span>{opt}</span>
              {selected !== null && isCorrect && <i className="fa-solid fa-check text-emerald-500"></i>}
              {selected !== null && isSelected && !isCorrect && <i className="fa-solid fa-xmark text-red-500"></i>}
            </button>
          );
        })}
      </div>
      {selected !== null && (
        <button onClick={handleNext} className="w-full mt-10 py-5 rounded-2xl bg-indigo-600 text-white font-black uppercase text-[10px] tracking-widest shadow-xl transition-all hover:bg-indigo-500">
          Pokračovat
        </button>
      )}
    </div>
  );
};

