const getBaseContents = (text: string, images: string[], files: StudyFile[]) => {
  const contents: any[] = [];
  if (text) contents.push({ text: `Zadání od uživatele: ${text}` });

  images.forEach((imgData) => {
    contents.push({
      inlineData: {
        mimeType: "image/jpeg",
        data: imgData.split(',')[1] || imgData
      }
    });
  });

  for (const file of files) {
    contents.push({
      inlineData: {
        mimeType: file.mimeType,
        data: file.data
      }
    });
  }
  return contents;
};

export const generateCurriculumPlan = async (subject: string, grade: number, level: string): Promise<CurriculumPlan> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const prompt = `Jsi expert na české školství. Vygeneruj systematický studijní plán pro předmět ${subject} pro ${grade}. ročník ${level === 'elementary' ? 'základní školy' : 'střední školy'}.
  Plán musí obsahovat cca 6-8 hlavních témat (kategorií).
  Vše v češtině a formátu JSON.`;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: [{ text: prompt }],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          subject: { type: Type.STRING },
          grade: { type: Type.NUMBER },
          topics: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.STRING },
                title: { type: Type.STRING },
                summary: {
                  type: Type.OBJECT,
                  properties: {
                    what: { type: Type.STRING },
                    how: { type: Type.STRING },
                    why: { type: Type.STRING }
                  },
                  required: ["what", "how", "why"]
                },
                mustKnow: { type: Type.ARRAY, items: { type: Type.STRING } }
              },
              required: ["id", "title", "summary", "mustKnow"]
            }
          }
        },
        required: ["subject", "grade", "topics"]
      }
    }
  });
  return JSON.parse(response.text);
};

export const generateInitialSummary = async (
  text: string,
  images: string[],
  files: StudyFile[],
  preAnalyses?: string[]
): Promise<Partial<StudyResult>> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const contents = getBaseContents(text, images, files);

  const instructions = `
    Jsi inteligentní studijní parťák Gymni Mate. Vytvoř hloubkový rozbor v češtině.
    DŮLEŽITÉ: Matematika a chemie VŽDY v KaTeXu ($vzorec$ nebo $$vzorec$$). Pro chemii \\ce{...}.
  `;

  if (preAnalyses?.length) contents.push({ text: `Analýza zdrojů: \n${preAnalyses.join('\n---\n')}` });
  contents.push({ text: instructions });

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: { parts: contents },
    config: {
      tools: [{ googleSearch: {} }],
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          learningGoal: { type: Type.STRING },
          whyImportant: { type: Type.STRING },
          prerequisites: { type: Type.ARRAY, items: { type: Type.STRING } },
          relatedTopics: { type: Type.ARRAY, items: { type: Type.STRING } },
          enhancementSuggestions: { type: Type.ARRAY, items: { type: Type.STRING } },
          fullSummary: { 
            type: Type.ARRAY, 
            items: { 
              type: Type.OBJECT, 
              properties: { text: { type: Type.STRING }, question: { type: Type.STRING } },
              required: ["text", "question"]
            } 
          },
          slides: { 
            type: Type.ARRAY, 
            items: { 
              type: Type.OBJECT, 
              properties: { title: { type: Type.STRING }, content: { type: Type.ARRAY, items: { type: Type.STRING } } }, 
              required: ["title", "content"] 
            } 
          }
        },
        required: ["title", "learningGoal", "whyImportant", "prerequisites", "relatedTopics", "enhancementSuggestions", "fullSummary", "slides"]
      },
      thinkingConfig: { thinkingBudget: 12000 }
    }
  });

  const parsed = JSON.parse(response.text);
  const searchSources = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((chunk: any) => ({
    uri: chunk.web?.uri,
    title: chunk.web?.title
  })).filter((s: any) => s.uri) || [];

  return { ...parsed, sources: searchSources };
};

