const InteractiveTest: React.FC<{ quiz: QuizSet }> = ({ quiz }) => {
  const [currentIdx, setCurrentIdx] = useState(0);
  const [selectedIdx, setSelectedIdx] = useState<number | null>(null);
  const [score, setScore] = useState(0);
  const [finished, setFinished] = useState(false);
  const handleSelect = (idx: number) => { if (selectedIdx !== null) return; setSelectedIdx(idx); if (idx === quiz.questions[currentIdx].correctIndex) setScore(s => s + 1); };
  const next = () => { if (currentIdx < quiz.questions.length - 1) { setCurrentIdx(c => c + 1); setSelectedIdx(null); } else { setFinished(true); } };
  if (finished) return <div className="p-10 text-center bg-zinc-950/50 rounded-[2.5rem] border border-white/5"><h4 className="text-3xl font-black text-indigo-500 mb-2">{Math.round((score/quiz.questions.length)*100)}%</h4><p className="text-[10px] font-black uppercase tracking-widest text-zinc-500">Test dokončen</p></div>;
  const q = quiz.questions[currentIdx];
  return (
    <div className="p-10 bg-zinc-950/80 border border-white/5 rounded-[2.5rem] animate-fade"><p className="text-xl font-bold text-white mb-8">{q.question}</p><div className="grid grid-cols-1 md:grid-cols-2 gap-4">{q.options.map((opt, i) => (<button key={i} onClick={() => handleSelect(i)} className={`p-5 rounded-2xl text-left text-sm font-bold border transition-all ${selectedIdx === null ? 'bg-white/5 border-white/10' : i === q.correctIndex ? 'bg-emerald-500/20 border-emerald-500 text-emerald-400' : selectedIdx === i ? 'bg-red-500/20 border-red-500 text-red-400' : 'opacity-20 border-white/10'}`}>{opt}</button>))}</div>{selectedIdx !== null && <button onClick={next} className="w-full mt-8 py-4 bg-indigo-600 rounded-2xl text-[10px] font-black uppercase tracking-widest text-white">Pokračovat</button>}</div>
  );
};

function decodeBase64(base64: string) { const binaryString = atob(base64); const len = binaryString.length; const bytes = new Uint8Array(len); for (let i = 0; i < len; i++) bytes[i] = binaryString.charCodeAt(i); return bytes; }
async function decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> { const dataInt16 = new Int16Array(data.buffer); const frameCount = dataInt16.length / numChannels; const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate); for (let channel = 0; channel < numChannels; channel++) { const channelData = buffer.getChannelData(channel); for (let i = 0; i < frameCount; i++) channelData[i] = dataInt16[i * numChannels + channel] / 32768.0; } return buffer; }

