import React, { useEffect, useState } from 'react';
import { DbConfig, StudyResult } from '../types';
import { fetchArchive, deleteArchiveItem } from '../services/dbService';

interface ArchiveItem {
  id: string;
  topic: string;
  image_url?: string;
  created_at: string;
  study_json: StudyResult;
}

interface ArchiveListProps {
  config: DbConfig;
  onOpenItem: (result: StudyResult) => void;
  limit?: number;
}

const ArchiveList: React.FC<ArchiveListProps> = ({ config, onOpenItem, limit }) => {
  const [items, setItems] = useState<ArchiveItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await fetchArchive(config);
      setItems(data.archive || []);
    } catch (e: any) {
      console.warn("Chyba při načítání archivu:", e);
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); }, [config]);

  const handleDelete = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (!confirm("Opravdu smazat tuto lekci? Tato akce je nevratná.")) return;
    try {
      await deleteArchiveItem(config, id);
      setItems(prev => prev.filter(i => i.id !== id));
    } catch (e: any) {
      alert("Chyba: " + e.message);
    }
  };

  if (loading) return (
    <div className="flex flex-col items-center justify-center py-32 gap-6 opacity-40">
      <div className="w-12 h-12 border-4 border-indigo-500/20 border-t-indigo-500 rounded-full animate-spin"></div>
      <p className="text-[10px] font-black uppercase tracking-[0.4em] text-indigo-400">Načítám Firestore archiv...</p>
    </div>
  );

  if (error) return (
    <div className="p-20 text-center glass-panel rounded-[3rem] border-red-500/20 max-w-2xl mx-auto">
      <div className="w-16 h-16 bg-red-500/10 text-red-500 rounded-2xl flex items-center justify-center mx-auto mb-6">
        <i className="fa-solid fa-triangle-exclamation text-2xl"></i>
      </div>
      <h3 className="text-xl font-black uppercase tracking-tight mb-2">Chyba databáze</h3>
      <p className="text-zinc-500 text-xs font-bold leading-relaxed mb-8">{error}</p>
      <button onClick={load} className="px-10 py-4 bg-zinc-900 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-zinc-800 transition-all border border-white/5">Zkusit znovu</button>
    </div>
  );

  const displayedItems = limit ? items.slice(0, limit) : items;

  if (items.length === 0) return (
    <div className="flex flex-col items-center justify-center py-32 opacity-20">
      <i className="fa-solid fa-box-open text-7xl mb-6"></i>
      <p className="text-xs font-black uppercase tracking-[0.3em]">Firestore archiv je zatím prázdný</p>
    </div>
  );

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 animate-fade pb-20">
      {displayedItems.map((item) => (
        <div 
          key={item.id} 
          onClick={() => onOpenItem(item.study_json)}
          className="group relative bg-zinc-900/40 border border-white/5 rounded-[3rem] overflow-hidden hover:border-indigo-500/40 transition-all cursor-pointer shadow-2xl hover:shadow-indigo-500/10 flex flex-col"
        >
          {item.image_url ? (
            <div className="h-48 overflow-hidden relative shrink-0">
              <img src={item.image_url} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-1000" alt={item.topic} />
              <div className="absolute inset-0 bg-gradient-to-t from-[#030712] via-transparent to-transparent"></div>
            </div>
          ) : (
            <div className="h-48 bg-zinc-950 flex items-center justify-center shrink-0">
               <i className="fa-solid fa-brain text-zinc-800 text-6xl"></i>
            </div>
          )}

          <div className="p-10 flex-grow flex flex-col">
            <div className="flex items-center gap-3 mb-4">
              <div className="w-2 h-2 rounded-full bg-indigo-500"></div>
              <span className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-500">
                {new Date(item.created_at).toLocaleDateString('cs-CZ', { day: 'numeric', month: 'long' })}
              </span>
            </div>
            <h3 className="font-black text-xl uppercase tracking-tight text-white line-clamp-2 leading-tight flex-grow">{item.topic}</h3>

            <div className="flex items-center justify-between mt-10 pt-6 border-t border-white/5">
              <div className="flex gap-4">
                <div className="flex items-center gap-1.5 text-zinc-600">
                  <i className="fa-solid fa-file-lines text-[10px]"></i>
                  <span className="text-[9px] font-black">{item.study_json?.fullSummary?.length || 0}</span>
                </div>
                <div className="flex items-center gap-1.5 text-zinc-600">
                  <i className="fa-solid fa-clone text-[10px]"></i>
                  <span className="text-[9px] font-black">{item.study_json?.flashcards?.length || 0}</span>
                </div>
              </div>
              <button 
                onClick={(e) => handleDelete(e, item.id)}
                className="w-10 h-10 rounded-xl bg-red-500/5 text-red-500/40 hover:bg-red-500 hover:text-white transition-all flex items-center justify-center border border-red-500/10"
              >
                <i className="fa-solid fa-trash-can text-xs"></i>
              </button>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
};

