    topic: string;
    originalImage: string | null;
    videoUrl: string | null;
    fullStudyResult: StudyResult;
  }
) => {
  let cloudSuccess = false;
  let cloudId = null;

  // --- 1. ZKUSÍME CLOUD ---
  if (useFirestore && db) {
    try {
      const colRef = collection(db, "lessons");
      const docRef = await addDoc(colRef, {
        topic: data.topic,
        video_url: data.videoUrl || '',
        study_json: JSON.stringify(data.fullStudyResult),
        image_url: data.originalImage,
        created_at: serverTimestamp(),
        projectId: firebaseConfig.projectId
      });
      cloudId = docRef.id;
      cloudSuccess = true;
    } catch (e) {
      console.error("Firestore Save Error:", e);
    }
  }

  // --- 2. VŽDY ULOŽÍME LOKÁLNĚ (jako zálohu nebo hlavní úložiště) ---
  try {
    const rawData = localStorage.getItem(STORAGE_KEY);
    const archive: LocalArchiveItem[] = rawData ? JSON.parse(rawData) : [];

    // Pokud už jsme uložili do cloudu, lokálně to uložíme jen pokud tam ještě není (prevence duplicit při refresh)
    const newItem: LocalArchiveItem = {
      id: cloudId || ("local_" + Math.random().toString(36).substring(2, 11)),
      topic: data.topic,
      image_url: data.originalImage,
      created_at: new Date().toISOString(),
      study_json: JSON.stringify(data.fullStudyResult)
    };

    // Omezíme duplicitu témat v lokálním archivu pro přehlednost
    const filtered = archive.filter(item => item.topic !== data.topic);
    filtered.unshift(newItem);

    localStorage.setItem(STORAGE_KEY, JSON.stringify(filtered.slice(0, 50))); // Limit 50 lekcí lokálně
    return { success: true, id: newItem.id };
  } catch (err) {
    if (cloudSuccess) return { success: true, id: cloudId };
    throw new Error("Nepodařilo se uložit data.");
  }
};

export const fetchArchive = async (config: DbConfig) => {
  let cloudArchive: any[] = [];

  // Zkusíme cloud
  if (useFirestore && db) {
    try {
      const colRef = collection(db, "lessons");
      const q = query(colRef, orderBy("created_at", "desc"));
      const querySnapshot = await getDocs(q);
      cloudArchive = querySnapshot.docs.map(docSnap => {
        const data = docSnap.data();
        return {
          id: docSnap.id,
          topic: data.topic,
          image_url: data.image_url,
          created_at: (data.created_at as Timestamp)?.toDate()?.toISOString() || new Date().toISOString(),
          study_json: JSON.parse(data.study_json)
        };
      });
    } catch (e) {
      console.warn("Firestore fetch failed:", e);
    }
  }

  // Načteme lokální data
  try {
    const rawData = localStorage.getItem(STORAGE_KEY);
    const localArchive: LocalArchiveItem[] = rawData ? JSON.parse(rawData) : [];
    const localItems = localArchive.map(item => ({
      ...item,
      study_json: JSON.parse(item.study_json)
    }));

    // Sloučení: prioritní jsou unikátní položky z obou zdrojů
    const combined = [...cloudArchive];
    localItems.forEach(l => {
      if (!combined.some(c => c.topic === l.topic)) {
