import { 
  Subject, 
  UserProfile, 
  DbConfig, 
  StudyResult, 
  StudyFile, 
  YouTubeVideo, 
  WebPage, 
  ProcessingState 
} from './types.tsx';

import { 
  generateInitialSummary, 
  generateExtendedStudy, 
  generateTopicImage 
} from './services/geminiService.ts';

import { storeInArchive, ORACLE_SERVER_URL, ORACLE_API_SECRET } from './services/dbService.ts';

import Sidebar, { PageId } from './components/Sidebar.tsx';
import StudyInput from './components/StudyInput.tsx';
import StudyOutput from './components/StudyOutput.tsx';
import SubjectBar, { SUBJECTS } from './components/SubjectBar.tsx';
import CurriculumGuide from './components/CurriculumGuide.tsx';
import ArchiveList from './components/ArchiveList.tsx';
import TeacherChat from './components/TeacherChat.tsx';
import AIAgent from './components/AIAgent.tsx';
import LoginModal from './components/LoginModal.tsx';
import SettingsModal from './components/SettingsModal.tsx';
import Calendar from './components/Calendar.tsx';
import RecentLessonsSidebar from './components/RecentLessonsSidebar.tsx';

const App: React.FC = () => {
  // --- UI STATE ---
  const [activePage, setActivePage] = useState<PageId>('home');
  const [activeSubject, setActiveSubject] = useState<Subject>(SUBJECTS[0]);
  const [isSubjectBarOpen, setIsSubjectBarOpen] = useState(false);
  const [isRecentSidebarOpen, setIsRecentSidebarOpen] = useState(false);
  const [isLoginModalOpen, setIsLoginModalOpen] = useState(false);
  const [isSettingsModalOpen, setIsSettingsModalOpen] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // --- APP STATE ---
  const [userProfile, setUserProfile] = useState<UserProfile>({
    email: '',
    isLoggedIn: false,
    role: 'student'
  });

  const [dbConfig, setDbConfig] = useState<DbConfig>({
    url: ORACLE_SERVER_URL,
    secret: ORACLE_API_SECRET
  });

  // --- INPUT STATE ---
  const [inputText, setInputText] = useState('');
  const [images, setImages] = useState<string[]>([]);
  const [files, setFiles] = useState<StudyFile[]>([]);
  const [ytVideos, setYtVideos] = useState<YouTubeVideo[]>([]);
  const [webPages, setWebPages] = useState<WebPage[]>([]);

  // --- PROCESSING STATE ---
  const [proc, setProc] = useState<ProcessingState>({
    isLoadingInitial: false,
    isLoadingExtra: false,
    error: null,
    result: null
  });

  // --- HANDLERS ---
  const handleGenerate = async () => {
    setProc(p => ({ ...p, isLoadingInitial: true, error: null, result: null }));
    setActivePage('learn');

    try {
      const initial = await generateInitialSummary(
        inputText, 
        images, 
        files, 
        [...ytVideos, ...webPages].map(v => v.analysis || '').filter(a => a)
      );

      const partialResult = initial as StudyResult;
      setProc(p => ({ ...p, result: partialResult, isLoadingInitial: false, isLoadingExtra: true }));

      const [extended, topicImage] = await Promise.all([
        generateExtendedStudy(inputText, images, files),
        generateTopicImage(partialResult.title)
      ]);

      const finalResult: StudyResult = {
        ...partialResult,
        ...extended,
        generatedImage: topicImage
      };

      setProc(p => ({ ...p, result: finalResult, isLoadingExtra: false }));

      // Ukládání do archivu proběhne vždy (hybridní dbService to pošle do lokálu nebo cloudu)
      try {
        await storeInArchive(dbConfig, {
          topic: finalResult.title,
          originalImage: images[0] || null,
          videoUrl: ytVideos[0]?.url || null,
          fullStudyResult: finalResult
        });
      } catch (e) {
        console.warn("Uložení do archivu selhalo:", e);
      }

    } catch (err: any) {
      setProc(p => ({ ...p, error: err.message, isLoadingInitial: false, isLoadingExtra: false }));
    }
  };

  const handleReset = () => {
    setProc({ isLoadingInitial: false, isLoadingExtra: false, error: null, result: null });
    setInputText('');
    setImages([]);
    setFiles([]);
    setYtVideos([]);
    setWebPages([]);
    setActivePage('learn'); // Stay in learn page but reset
  };

  return (
    <div className="flex h-screen overflow-hidden bg-[#020617]">
      {/* LEFT SIDEBAR */}
      <Sidebar 
        activePage={activePage}
        onPageChange={setActivePage}
        hasResult={!!proc.result}
        userProfile={userProfile}
        onUpdateProfile={setUserProfile}
        onOpenLogin={() => setIsLoginModalOpen(true)}
        activeSubject={activeSubject}
        onToggleSubjectBar={() => setIsSubjectBarOpen(!isSubjectBarOpen)}
        onOpenSettings={() => setIsSettingsModalOpen(true)}
        isOpen={isSidebarOpen}
        onToggle={() => setIsSidebarOpen(!isSidebarOpen)}
      />

      {/* MAIN CONTENT AREA */}
      <div className="flex-grow flex flex-col min-w-0 bg-[#020617] relative">
        <div className="flex-grow overflow-y-auto no-scrollbar scroll-smooth">
          {activePage === 'home' && (
            <div className="max-w-6xl mx-auto py-16 px-8">
