}

const ArchiveList: React.FC<ArchiveListProps> = ({ config, onOpenItem, limit }) => {
  const [items, setItems] = useState<EnhancedArchiveItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await fetchArchive(config);
      setItems(data.archive || []);
    } catch (e: any) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); }, [config]);

  const handleDelete = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (!confirm("Opravdu smazat tuto lekci?")) return;
    try {
      await deleteArchiveItem(config, id);
      setItems(prev => prev.filter(i => i.id !== id));
    } catch (e: any) {
      alert("Chyba při mazání: " + e.message);
    }
  };

  if (loading) return (
    <div className="flex flex-col items-center justify-center py-32 gap-6 opacity-40">
      <div className="w-12 h-12 border-4 border-indigo-500/20 border-t-indigo-500 rounded-full animate-spin"></div>
      <p className="text-[10px] font-black uppercase tracking-[0.4em] text-indigo-400">Načítám archivy...</p>
    </div>
  );

  if (error) return (
    <div className="p-20 text-center glass-panel rounded-[3rem] border-red-500/20 max-w-2xl mx-auto">
      <h3 className="text-xl font-black uppercase tracking-tight mb-2">Chyba synchronizace</h3>
      <p className="text-zinc-500 text-xs mb-8">{error}</p>
      <button onClick={load} className="px-10 py-4 bg-zinc-900 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-zinc-800 transition-all">Zkusit znovu</button>
    </div>
  );

  const displayedItems = limit ? items.slice(0, limit) : items;

  if (items.length === 0) return (
    <div className="flex flex-col items-center justify-center py-32 opacity-20">
      <i className="fa-solid fa-box-open text-7xl mb-6"></i>
      <p className="text-xs font-black uppercase tracking-[0.3em]">Archiv je zatím prázdný</p>
    </div>
  );

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 animate-fade pb-20">
      {displayedItems.map((item) => (
        <div 
          key={item.id} 
          onClick={() => onOpenItem(item.study_json)}
          className="group relative bg-zinc-900/40 border border-white/5 rounded-[3rem] overflow-hidden hover:border-indigo-500/40 transition-all cursor-pointer shadow-2xl flex flex-col"
        >
          <div className="h-40 overflow-hidden relative shrink-0 bg-zinc-950">
            {item.image_url ? (
              <img src={item.image_url} className="w-full h-full object-cover opacity-60 group-hover:scale-110 transition-transform duration-1000" alt={item.topic} />
            ) : (
              <div className="w-full h-full flex items-center justify-center opacity-10">
                <i className="fa-solid fa-brain text-5xl"></i>
              </div>
            )}

            {/* Storage Badge */}
            <div className="absolute top-6 left-6 z-10">
              {item.storageSource === 'cloud' ? (
                <div className="flex items-center gap-2 px-3 py-1.5 rounded-xl bg-indigo-600/80 backdrop-blur-md border border-indigo-400/30 text-[8px] font-black uppercase tracking-widest text-white">
                  <i className="fa-solid fa-cloud"></i> Cloud
                </div>
              ) : (
                <div className="flex items-center gap-2 px-3 py-1.5 rounded-xl bg-zinc-800/80 backdrop-blur-md border border-white/10 text-[8px] font-black uppercase tracking-widest text-zinc-400">
                  <i className="fa-solid fa-folder"></i> Local
                </div>
              )}
            </div>
          </div>

          <div className="p-8 flex-grow flex flex-col">
            <h3 className="font-black text-lg uppercase tracking-tight text-white line-clamp-2 leading-tight flex-grow mb-6">{item.topic}</h3>

            <div className="flex items-center justify-between pt-6 border-t border-white/5">
              <span className="text-[9px] font-black uppercase tracking-widest text-zinc-600">
                {new Date(item.created_at).toLocaleDateString('cs-CZ')}
              </span>
              <button 
                onClick={(e) => handleDelete(e, item.id)}
                className="w-10 h-10 rounded-xl bg-red-500/5 text-red-500/30 hover:bg-red-600 hover:text-white transition-all flex items-center justify-center border border-red-500/10"
              >
                <i className="fa-solid fa-trash-can text-xs"></i>
              </button>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
};

