  const handleGenerate = async () => {
    systemLog("Spouštím Neural Engine...");
    setProc(p => ({ ...p, isLoadingInitial: true, error: null, result: null }));
    setActivePage('learn');

    try {
      systemLog("Generuji základní rozbor...");
      const initial = await generateInitialSummary(
        inputText, 
        images, 
        files, 
        [...ytVideos, ...webPages].map(v => v.analysis || '').filter(a => a)
      );

      const partialResult = initial as StudyResult;
      setProc(p => ({ ...p, result: partialResult, isLoadingInitial: false, isLoadingExtra: true }));

      systemLog("Rozšiřuji materiály (testy, mapy)...");
      const [extended, topicImage] = await Promise.all([
        generateExtendedStudy(inputText, images, files),
        generateTopicImage(partialResult.title)
      ]);

      const finalResult: StudyResult = {
        ...partialResult,
        ...extended,
        generatedImage: topicImage
      };

      setProc(p => ({ ...p, result: finalResult, isLoadingExtra: false }));
      systemLog("Lekce hotova. Archivuji.");

      await storeInArchive(dbConfig, {
        topic: finalResult.title,
        originalImage: images[0] || null,
        videoUrl: ytVideos[0]?.url || null,
        fullStudyResult: finalResult
      });

    } catch (err: any) {
      systemLog(`Kritická chyba: ${err.message}`);
      setProc(p => ({ ...p, error: err.message, isLoadingInitial: false, isLoadingExtra: false }));
    }
  };

  const handleReset = () => {
    setProc({ isLoadingInitial: false, isLoadingExtra: false, error: null, result: null });
    setInputText('');
    setImages([]);
    setFiles([]);
    setYtVideos([]);
    setWebPages([]);
    setActivePage('learn');
  };

  return (
    <div className="flex h-screen overflow-hidden bg-[#020617]">
      <SystemLog />

      <Sidebar 
        activePage={activePage}
        onPageChange={setActivePage}
        hasResult={!!proc.result}
        userProfile={userProfile}
        onUpdateProfile={setUserProfile}
        onOpenLogin={() => setIsLoginModalOpen(true)}
        activeSubject={activeSubject}
        onToggleSubjectBar={() => setIsSubjectBarOpen(!isSubjectBarOpen)}
        onOpenSettings={() => setIsSettingsModalOpen(true)}
        isOpen={isSidebarOpen}
        onToggle={() => setIsSidebarOpen(!isSidebarOpen)}
      />

      <div className="flex-grow flex flex-col min-w-0 bg-[#020617] relative">
        <div className="flex-grow overflow-y-auto no-scrollbar scroll-smooth">
          {activePage === 'home' && (
            <div className="max-w-6xl mx-auto py-16 px-8">
              <div className="mb-16 animate-fade">
                <p className="text-indigo-500 text-[10px] font-black uppercase tracking-[0.8em] mb-4">Neural Study Interface</p>
                <h2 className="text-5xl md:text-7xl font-black uppercase text-white tracking-tighter leading-none mb-12">
                  Vítej zpět,<br/><span className="text-indigo-600">Studijní parťáku</span>
                </h2>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                  <Calendar role={userProfile.role} />
                  <div className="space-y-6">
                    <div className="glass-panel p-10 rounded-[3rem] border-white/5 flex items-center justify-between group cursor-pointer hover:border-indigo-500/30 transition-all shadow-2xl" onClick={() => setActivePage('archive')}>
                       <div className="space-y-2">
                         <p className="text-[10px] font-black uppercase text-indigo-500 tracking-widest">Aktivní modul</p>
                         <h4 className="text-2xl font-black text-white uppercase tracking-tight">Knihovna znalostí</h4>
                       </div>
                       <div className="w-12 h-12 rounded-2xl bg-white/5 flex items-center justify-center text-zinc-500 group-hover:text-white group-hover:bg-indigo-600 transition-all">
                          <i className="fa-solid fa-arrow-right"></i>
                       </div>
                    </div>
                    <div className="p-10 rounded-[3rem] bg-indigo-600/5 border border-indigo-500/10 shadow-2xl">
                       <h4 className="text-[10px] font-black uppercase text-zinc-600 mb-8 tracking-widest">Tvůj progresivní index</h4>
                       <div className="space-y-5">
                         <div className="flex justify-between items-center text-[10px] font-black uppercase text-white tracking-widest">
                            <span>Splněné cíle</span>
                            <span className="text-indigo-500 text-lg">12 / 20</span>
                         </div>
                         <div className="h-2 w-full bg-white/5 rounded-full overflow-hidden">
                            <div className="h-full bg-indigo-500 w-[60%] shadow-[0_0_20px_rgba(99,102,241,0.6)]"></div>
                         </div>
                       </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}

          {activePage === 'learn' && (
            <div className="max-w-7xl mx-auto py-12 px-6">
              {!proc.result && !proc.isLoadingInitial && (
                <div className="space-y-16 animate-fade py-10">
                  <div className="text-center space-y-6">
                    <p className="text-indigo-500 text-[10px] font-black uppercase tracking-[0.8em]">Input Knowledge Gateway</p>
                    <h2 className="text-5xl md:text-8xl font-black uppercase text-white tracking-tighter leading-none">
                      Co se dnes <br/><span className="text-indigo-600">naučíme?</span>
                    </h2>
                    <p className="text-zinc-500 font-bold text-sm uppercase tracking-[0.3em] max-w-xl mx-auto leading-relaxed">
                      Vložte text, soubory nebo fotky a nechte Gemini vytvořit váš studijní vesmír.
                    </p>
                  </div>

                  <StudyInput 
                    text={inputText} setText={setInputText}
                    images={images} setImages={setImages}
                    files={files} setFiles={setFiles}
                    ytVideos={ytVideos} setYtVideos={setYtVideos}
                    webPages={webPages} setWebPages={setWebPages}
                    onGenerate={handleGenerate}
                    isLoading={proc.isLoadingInitial}
                  />
                </div>
              )}

              {proc.isLoadingInitial && (
                <div className="flex flex-col items-center justify-center py-40 animate-fade gap-12">
                   <div className="relative">
                      <div className="w-40 h-40 border-4 border-indigo-500/10 border-t-indigo-500 rounded-full animate-spin"></div>
                      <div className="absolute inset-0 flex items-center justify-center text-indigo-500">
                         <i className="fa-solid fa-brain text-4xl animate-pulse"></i>
                      </div>
                   </div>
                   <div className="text-center space-y-4">
                      <p className="text-3xl font-black uppercase tracking-tighter text-white">Neural Engine zpracovává data</p>
                      <p className="text-[10px] text-zinc-600 font-black uppercase tracking-[0.5em] animate-pulse">Buduji tvou novou znalostní architekturu...</p>
                   </div>
                </div>
              )}

              {proc.result && (
                <StudyOutput 
                  result={proc.result}
                  onReset={handleReset}
                  onUpdateResult={(updated) => setProc(p => ({ ...p, result: updated }))}
                  onGenerateTopic={(t) => { setInputText(t); handleGenerate(); }}
                  isLoadingExtra={proc.isLoadingExtra}
                  isLoadingInitial={proc.isLoadingInitial}
                  originalImage={images[0] || null}
                  originalText={inputText}
                  activeSubject={activeSubject}
                  dbConfig={dbConfig}
                />
              )}
            </div>
          )}

          {activePage === 'curriculum' && (
            <CurriculumGuide 
              activeSubject={activeSubject} 
              onGenerateLesson={(topic) => { setInputText(topic); handleGenerate(); }} 
            />
          )}

          {activePage === 'archive' && (
            <div className="max-w-6xl mx-auto py-16 px-8">
               <div className="mb-16">
                  <p className="text-indigo-500 text-[10px] font-black uppercase tracking-[0.8em] mb-4">Cloud Knowledge Repository</p>
                  <h2 className="text-5xl font-black uppercase text-white tracking-tighter">Archiv tvých lekcí</h2>
               </div>
               <ArchiveList 
                 config={dbConfig} 
                 onOpenItem={(res) => { setProc(p => ({ ...p, result: res })); setActivePage('learn'); }} 
               />
            </div>
          )}

          {activePage === 'chat' && (
            <div className="h-full p-8 overflow-hidden">
               <TeacherChat initialSubject={activeSubject.name} />
            </div>
          )}
        </div>
      </div>

      <RecentLessonsSidebar 
        config={dbConfig}
        onOpenItem={(res) => { setProc(p => ({ ...p, result: res })); setActivePage('learn'); }}
        isOpen={isRecentSidebarOpen}
        onToggle={() => setIsRecentSidebarOpen(!isRecentSidebarOpen)}
      />

      <AIAgent currentContext={proc.result} />

      <SubjectBar 
        activeSubjectId={activeSubject.id}
        onSelect={setActiveSubject}
        isOpen={isSubjectBarOpen}
        onClose={() => setIsSubjectBarOpen(false)}
      />

      {isLoginModalOpen && (
        <LoginModal 
          onLogin={(profile) => { setUserProfile(profile); setIsLoginModalOpen(false); }} 
          onClose={() => setIsLoginModalOpen(false)} 
        />
      )}

      {isSettingsModalOpen && (
        <SettingsModal 
          config={dbConfig} 
          onSave={setDbConfig} 
          onClose={() => setIsSettingsModalOpen(false)} 
        />
      )}

      {proc.error && (
        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 z-[3000] p-8 bg-red-600 rounded-[2.5rem] text-white font-black text-xs uppercase tracking-widest shadow-2xl flex items-center gap-8 animate-fade">
           <i className="fa-solid fa-triangle-exclamation text-2xl"></i>
           <span>{proc.error}</span>
           <button onClick={() => setProc(p => ({ ...p, error: null }))} className="w-10 h-10 rounded-full bg-black/20 hover:bg-black/40 flex items-center justify-center transition-all"><i className="fa-solid fa-xmark"></i></button>
        </div>
      )}
    </div>
  );
};

export default App;
